INPUT.SQL:
select g.maloprodajaglaid, g.datumdok as [Datum1100], g.broj as [Broj1500], g.napomena as [Napomena2700], g.nabiznos as [Nab.iznos1200] 
			from maloprodajagla g with(nolock) 
			inner join totalgenmultiselecttemp t on g.maloprodajaglaid = t.id where t.operateriid = @@operateriid and susersname = suser_name()
